// The build-time theme (the library's own) as one `AppTheme`: the same tokens and finishes an app
// built on another theme does not have, for it to switch back to while it runs (`selectTheme`,
// `currentTheme`). `shadcn-nsh add theme-default` copies this directory into the app's
// `themes/default/`; it is the app's, then, to change. Its two files are the build-time ones,
// copied byte for byte.
import type { AppTheme } from "@shadcn-nsh/theme";

import semantics from "./semantics.json";
import theme from "./theme.json";

/** The default look (the citrus accent, the graphite surfaces, the 10-point base radius: 8-point controls, 14-point cards) as a theme:
 * what an app built on another one switches back to. */
export const defaultTheme: AppTheme = {
  id: "default",
  label: "NSH Gallery UI",
  theme,
  semantics: semantics as AppTheme["semantics"],
};

export default defaultTheme;
